`validators.py`:

```
"""Validators V1..V6 over depot run outputs. Each subclasses ``Check`` from ``checks_base``.

Callers use ``VN().run(items)``, which returns a ``CheckResult``. Empty input is refused by
the base class before ``check`` is called, so these methods only see non-empty input.
"""
from __future__ import annotations

from checks_base import Check

# Notification types the spec says the depot emits:
# OVERDRAWN (C20), SUPPLIER_SUSPENDED (C17), REORDER (C14), AUDIT_MISMATCH (C22), EXPIRY (C13).
REQUIRED_NOTIFICATION_TYPES = frozenset({
    "OVERDRAWN",
    "SUPPLIER_SUSPENDED",
    "REORDER",
    "AUDIT_MISMATCH",
    "EXPIRY",
})


class V1(Check):
    """rows: every report row's value equals units * unit_cost."""

    name = "rows"

    def check(self, items):
        mismatches = []
        for row in items:
            expected = row["units"] * row["unit_cost"]
            if row["value_cents"] != expected:
                mismatches.append({
                    "sku": row["sku"],
                    "wh": row["wh"],
                    "expected": expected,
                    "actual": row["value_cents"],
                })
        return len(mismatches) == 0, {"checked": len(items), "mismatches": mismatches}


class V2(Check):
    """runs: every notification type the spec defines was seen across the runs."""

    name = "runs"

    def check(self, items):
        seen = set()
        for run in items:
            for note in run:
                seen.add(note[0])
        missing = sorted(REQUIRED_NOTIFICATION_TYPES - seen)
        return len(missing) == 0, {
            "required": sorted(REQUIRED_NOTIFICATION_TYPES),
            "seen": sorted(seen, key=str),
            "missing": missing,
        }


class V3(Check):
    """pairs: two runs with the same seed produce identical output."""

    name = "pairs"

    def check(self, items):
        differing = [p["seed"] for p in items if p["a"] != p["b"]]
        return len(differing) == 0, {"pairs": len(items), "differing_seeds": differing}


class V4(Check):
    """days: storage cost on each day stayed within that day's budget."""

    name = "days"

    def check(self, items):
        over = [
            {
                "day": d["day"],
                "storage_cost_cents": d["storage_cost_cents"],
                "budget_cents": d["budget_cents"],
            }
            for d in items
            if d["storage_cost_cents"] > d["budget_cents"]
        ]
        return len(over) == 0, {"days": len(items), "over_budget": over}


class V5(Check):
    """clauses: every clause entry has at least one non-blank test name."""

    name = "clauses"

    def check(self, items):
        untested = []
        for entry in items:
            tests = entry["tests"]
            if isinstance(tests, str):
                tests = [tests]
            if not any(isinstance(t, str) and t.strip() for t in tests):
                untested.append(entry["clause_id"])
        return len(untested) == 0, {"clauses": len(items), "untested": untested}


class V6(Check):
    """pairs: two implementations agree on every compared pair."""

    name = "pairs"

    def check(self, items):
        disagreements = [p["key"] for p in items if p["a"] != p["b"]]
        return len(disagreements) == 0, {
            "compared": len(items),
            "disagreements": disagreements,
        }
```

`checks_base.py`:

```
"""The ``Check`` base class: a check never passes on nothing (brief 3, and E2's guard condition).

``Check.run(items)`` returns ``failed: empty input`` for empty or all-unmeasured input *before*
calling the subclass, and ``failed: nothing measured`` when the subclass measured nothing. The
harness's own checks (presence, reach, parity, mutation) subclass it, and so do the agent's
validators in E2's guard condition (the agent gets this file as ``checks_base.py``).

This file is standard-library only so it can be copied verbatim into the agent's repo.
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import Any


@dataclass
class CheckResult:
    passed: bool
    measured: Any
    reason: str = ""

    def __iter__(self):  # allows ``passed, measured = check.run(x)``
        yield self.passed
        yield self.measured

    def __bool__(self) -> bool:
        return bool(self.passed)


def is_empty(value: Any) -> bool:
    """True for None, empty containers, and containers whose every leaf is None or empty."""
    if value is None:
        return True
    if isinstance(value, (str, bytes)):
        return len(value) == 0
    if isinstance(value, dict):
        return len(value) == 0 or all(is_empty(v) for v in value.values())
    if isinstance(value, (list, tuple, set, frozenset)):
        return len(value) == 0 or all(is_empty(v) for v in value)
    return False


class Check:
    """Subclasses implement ``check(items) -> (passed, measured)``; callers use ``run(items)``."""

    name = "check"

    def run(self, items: Any) -> CheckResult:
        if hasattr(items, "__next__"):  # a lazy source of runs: materialise before judging emptiness
            items = list(items)
        if is_empty(items):
            return CheckResult(False, None, "failed: empty input")
        try:
            passed, measured = self.check(items)
        except Exception as exc:  # a check that crashes has not passed
            return CheckResult(False, None, f"failed: {type(exc).__name__}: {exc}")
        if is_empty(measured):
            return CheckResult(False, measured, "failed: nothing measured")
        return CheckResult(bool(passed), measured, "" if passed else "failed")

    def check(self, items: Any) -> tuple[bool, Any]:  # pragma: no cover - abstract
        raise NotImplementedError
```
